[CmdletBinding()]
param([Parameter(Mandatory)][string]$ServerName,[Parameter(Mandatory)][string]$ClaimId,[string]$ConfigPath=(Join-Path (Split-Path -Parent $PSScriptRoot) 'config\agents.json'),[string]$CodexHome)
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';if(-not(Get-Command Get-EcosystemStateRoot -ErrorAction SilentlyContinue)){Import-Module (Join-Path $PSScriptRoot 'AgentEcosystem.psm1') -Global}
$config=Get-EcosystemConfig -ConfigPath $ConfigPath -CodexHome $CodexHome;$root=Join-Path (Get-EcosystemStateRoot -Config $config -CodexHome $CodexHome) 'health\mcp';$path=Join-Path $root ($ServerName+'.json');$lock=$path+'.lock';$stream=[IO.File]::Open($lock,[IO.FileMode]::OpenOrCreate,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None);try{if(-not(Test-Path $path)){return $false};$state=Get-Content $path -Raw|ConvertFrom-Json;$now=[DateTime]::UtcNow;if([string]$state.state -eq 'open' -and [DateTimeOffset]::Parse([string]$state.retryAfterUtc).UtcDateTime -le $now){$state.state='half-open';$state|Add-Member -NotePropertyName canaryClaimId -NotePropertyValue $ClaimId -Force;$state|Add-Member -NotePropertyName probeSuccessCount -NotePropertyValue 0 -Force}elseif([string]$state.state -eq 'half-open' -and [string]::IsNullOrWhiteSpace([string]$state.canaryClaimId)){$state.canaryClaimId=$ClaimId}elseif([string]$state.state -eq 'half-open' -and [string]$state.canaryClaimId -ne $ClaimId){return $false}else{return $false};$tmp=$path+'.'+[guid]::NewGuid().ToString('N')+'.tmp';[IO.File]::WriteAllText($tmp,(($state|ConvertTo-Json -Depth 8)+[Environment]::NewLine));Move-Item $tmp $path -Force;$true}finally{$stream.Dispose()}
